import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

async function CardStatsSkeleton() {
  const res = await fetch('https://api.example.com/dashboard/stats', {
    next: { revalidate: 60 },
  })
  const data = await res.json()
  return <CardStats totalRevenue={data.totalRevenue} totalInvoices={data.totalInvoices} />
}

async function RevenueChartSkeleton() {
  const res = await fetch('https://api.example.com/dashboard/revenue', {
    next: { revalidate: 60 },
  })
  const data = await res.json()
  return <RevenueChart revenue={data.revenue} />
}

async function LatestInvoicesSkeleton() {
  const res = await fetch('https://api.example.com/dashboard/invoices', {
    next: { revalidate: 60 },
  })
  const data = await res.json()
  return <LatestInvoices invoices={data.invoices} />
}

function CardStatsFallback() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card skeleton" />
      <div className="card skeleton" />
    </div>
  )
}

function RevenueChartFallback() {
  return <div className="chart skeleton" />
}

function LatestInvoicesFallback() {
  return <div className="invoices skeleton" />
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsFallback />}>
        <CardStatsSkeleton />
      </Suspense>
      <Suspense fallback={<RevenueChartFallback />}>
        <RevenueChartSkeleton />
      </Suspense>
      <Suspense fallback={<LatestInvoicesFallback />}>
        <LatestInvoicesSkeleton />
      </Suspense>
    </main>
  )
}

